/**  A flattened block node for rendering, produced by `project_landmark`. */
export type RenderNode_Serialize = {
  id: MarkID;
  data: MarkData_Serialize;
  depth: number;
  fractional_index: string;
  parent_id: MarkID | null;
  is_leaf_landmark: boolean;
};

export type RichText = RichText_Serialize;

/**  Deserialization DTO that routes through `RichText::new()`. */
export type RichTextDTO = RichTextDTO_Serialize;

/**  Deserialization DTO that routes through `RichText::new()`. */
export type RichTextDTO_Deserialize = {
  segments: TextSegment_Deserialize[];
};

/**  Deserialization DTO that routes through `RichText::new()`. */
export type RichTextDTO_Serialize = {
  segments: TextSegment_Serialize[];
};

export type RichText_Deserialize = RichTextDTO_Deserialize;

export type RichText_Serialize = {
  plain_text: string;
  segments: TextSegment_Serialize[];
};

/**  Where a setup code should be routed. */
export type SetupCode =
  /**  A pairing payload (JSON string) for `pairing_join`. */
  | { kind: "pairing"; value: string }
  /**  A recovery phrase for `identity_import`. */
  | { kind: "phrase"; value: string }
  /**  Unrecognized — surface a "not a setup code" error to the user. */
  | { kind: "unknown" };

export type Size =
  /**  Fixed size in pixels */
  | { type: "fixed"; value: number }
  /**  Fractional size of available space */
  | { type: "ratio"; value: number | null }
  /**  Auto-size based on content (and table width) */
  | { type: "auto" }
  | { type: "min" }
  | { type: "max" };

/**  Result of a split operation. */
export type SplitResult = SplitResult_Serialize;

/**  Result of a split operation. */
export type SplitResult_Deserialize = {
  new_mark_id: MarkID;
  blocks: RenderNode_Deserialize[];
};

/**  Result of a split operation. */
export type SplitResult_Serialize = {
  new_mark_id: MarkID;
  blocks: RenderNode_Serialize[];
};

/**  Result of probing the configured Station — the "ping". */
export type StationStatus = {
  configured: boolean;
  reachable: boolean;
  /**
   *  Whether the Station serves this device's Territory (false until
   *  registered, or when probing without a local Territory).
   */
  servesTerritory: boolean;
  latencyMs: number | null;
  error: string | null;
};

/**
 *  One sighted device (Vessel) from the Station's device registry, with its
 *  attribution verified client-side against the claimed identity.
 */
export type SyncDevice = {
  /**  The identity behind the device, as hex `MemberID`. */
  memberId: string;
  /**  The device's public key (its VesselID), as hex. */
  deviceKey: string;
  /**  Belongs to this device's identity. */
  mine: boolean;
  /**  Is this very device. */
  thisDevice: boolean;
  /**
   *  Station-attested unix seconds — presence metadata, not verified.
   *  `f64` because specta forbids `u64` at the IPC boundary.
   */
  firstSeen: number | null;
  lastSeen: number | null;
  /**
   *  Live-session presence: true only while the device holds an open
   *  session with the Station.
   */
  connected: boolean;
};

/**
 *  Live sync state for the UI: what moved, what is waiting, and whether the
 *  live session is up. Complements [`SyncStatus`] (lifecycle) with runtime
 *  observability — including the log-growth measurement and the
 *  deferred-operation count, so a permanently unresolved reference is
 *  visible rather than silent.
 */
export type SyncState = {
  /**  Milliseconds since epoch of the last completed sync, if any. */
  lastSyncMs: number | null;
  /**  Locally applied op batches still queued for publication. */
  pendingPublications: number;
  /**  Ops deferred on a Mark whose creation has not folded. */
  deferredOps: number;
  /**  Notices held in the Territory (log-growth measurement). */
  notices: number;
  /**  On-disk size of the Territory hold in bytes. */
  holdBytes: number | null;
  /**  Whether the maintained live subscription is currently connected. */
  liveConnected: boolean;
};

/**
 *  Where this device stands in the sync lifecycle — the UI's single source
 *  for gating onboarding vs. settings surfaces.
 */
export type SyncStatus = {
  hasIdentity: boolean;
  /**
   *  The identity's `MemberID` as hex (the user ID — the key *is* the
   *  account).
   */
  memberId: string | null;
  /**  This device's key-derivation index under the identity. */
  deviceIndex: number | null;
  hasTerritory: boolean;
  /**  The sync Territory's ID as hex. */
  territoryId: string | null;
  stationConfigured: boolean;
  /**
   *  The configured Station address, as its JSON form (what `station-run`
   *  publishes to `station.addr`).
   */
  stationAddr: string | null;
};

export type Territory = {
  id: string;
  name: string;
  kind: TerritoryKind;
  path: string | null;
  createdAt: string;
  lastOpenedAt: string | null;
};

export type TerritoryKind = "managed" | "external";

/**  Types of text formatting. */
export type TextMarkKind =
  | "bold"
  | "italic"
  | "underline"
  | "strikethrough"
  | "superscript"
  | "subscript"
  | "code"
  | "link"
  | "mention"
  | "highlight"
  | "color"
  | "font-size"
  | "font-family"
  | "math"
  | "spoiler";

/**  A contiguous run of text sharing the same set of inline marks. */
export type TextSegment = TextSegment_Serialize;

/**  A contiguous run of text sharing the same set of inline marks. */
export type TextSegment_Deserialize = {
  text: string;
  marks?: InlineMark_Deserialize[];
};

/**  A contiguous run of text sharing the same set of inline marks. */
export type TextSegment_Serialize = {
  text: string;
  marks?: InlineMark_Serialize[];
};

/**  Result of an undo/redo operation. */
export type UndoRedoResult = UndoRedoResult_Serialize;

/**  Result of an undo/redo operation. */
